UPDATE products SET title='WarmPocket Water-Filled Portable Heat Therapy Bag', description='The bag holds 800 milliliters and has a screw cap with a silicone sealing ring; the outer cover is machine washable. The product does not include a heating element. Add warm water at a suitable temperature according to the instructions and check for leaks.' WHERE rowid=132;
