UPDATE products SET title='KeyBrush Dual-Head Keyboard Cleaning Brush', description='One end has soft bristles for narrow gaps, while the other is a retractable long-bristle brush, suitable for removing debris between keycaps. The handle has no metal scraper and can be washed and air-dried.' WHERE rowid=141;
UPDATE products SET title='HubDesk Four-Port USB 3.0 Hub', description='The four ports are arranged horizontally, and the cable is 60 centimeters long. It has a dedicated power input but does not include a power adapter. A separate power supply is required when using high-power hard drives simultaneously.' WHERE rowid=142;
